contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance > 0);
        uint balBefore = address(c).balance;
        uint selfBefore = address(this).balance;
        c.sendMoney(address(this), amount); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;
        uint selfAfter = address(this).balance;
        assert(
            (balAfter == balBefore && selfAfter == selfBefore) ||
            (balBefore >= amount && balAfter == balBefore - amount && selfAfter == selfBefore + amount)
        );
    }
    receive() external payable {}
}

